{"action":"write","path":"sections/03-mission.html","content":"<style>
#mission {
  background: #fff8f0;
  color: #1e3d2f;
  padding: 64px 24px;
  border-top: 4px solid #8a5a3a;
}
#mission h2 {
  font-family: Georgia, serif;
  font-size: 36px;
  line-height: 1.2;
  margin: 0 0 16px;
  color: #1e3d2f;
}
#mission .mission-lead {
  font-size: 18px;
  line-height: 1.7;
  max-width: 720px;
  margin: 0 auto 24px;
  color: #2a4a3a;
}
#mission .mission-note {
  font-size: 16px;
  line-height: 1.7;
  max-width: 720px;
  margin: 0 auto;
  padding: 20px;
  background: #f1e6d8;
  border-left: 4px solid #8a5a3a;
  border-radius: 8px;
