{"action":"write","path":"sections/06-events.html","content":"<section id="events">
  <h2>Events</h2>
  <style>
    #events {font-family: system-ui, -apple-system, sans-serif; color:#1e2a1e; background:#fff8f0; padding:48px 24px;}
    #events h2 {font-size:32px; margin:0 0 24px; color:#1e2a1e;}
    #events .events-grid {display:grid; gap:24px; grid-template-columns:repeat(auto-fit, minmax(260px,1fr));}
    #events article[data-event] {background:#fff; border:1px solid #e6d9c9; border-radius:12px; padding:20px; display:flex; flex-direction:column; gap:8px;}
    #events article[data-event] h3 {margin:0; font-size:20px; color:#1e2a1e;}
    #events article[data-event] time {font-weight:600; color:#8a5a2a;}
    #events article[data-event] p {margin:0; color:#3a3a3a; line-height:1.5;}
